package android.util;import java.io.*;import java.nio.file.*;public class AtomicFile{final File base,temp;public AtomicFile(File f){base=f;temp=new File(f.toString()+".tmp");}public FileInputStream openRead()throws IOException{return new FileInputStream(base);}public FileOutputStream startWrite()throws IOException{return new FileOutputStream(temp);}public void finishWrite(FileOutputStream out)throws IOException{out.close();Files.move(temp.toPath(),base.toPath(),StandardCopyOption.REPLACE_EXISTING);}public void failWrite(FileOutputStream out){try{out.close();}catch(IOException ignored){}temp.delete();}}
